{
  "story_id": "K04",
  "test_cases": [
    {
      "case_id": "TC01",
      "title": "Application submitted immediately before list replacement uses the previous list",
      "covers": ["AC1"],
      "preconditions": [
        "The previous sanctions list contains a full-name-and-date-of-birth match for the test applicant.",
        "The new sanctions list contains no match for the test applicant."
      ],
      "steps": [
        "Submit an application at 01:59:59 UTC on the list replacement day.",
        "Inspect the list version used for screening and the screening result."
      ],
      "expected_result": "The application is screened against the previous day's list and is identified as a match."
    },
    {
      "case_id": "TC02",
      "title": "Application submitted at list replacement time uses the new list",
      "covers": ["AC1"],
      "preconditions": [
        "The previous sanctions list contains no match for the test applicant.",
        "The new sanctions list contains a full-name-and-date-of-birth match for the test applicant."
      ],
      "steps": [
        "Submit an application at exactly 02:00:00 UTC on the list replacement day.",
        "Inspect the list version used for screening and the screening result."
      ],
      "expected_result": "The application is screened against the new day's list and is identified as a match."
    },
    {
      "case_id": "TC03",
      "title": "Full name and date-of-birth match blocks the application and alerts compliance",
      "covers": ["AC2"],
      "preconditions": [
        "The active sanctions list contains an entry matching the applicant's full name and date of birth.",
        "The compliance alert mechanism is available."
      ],
      "steps": [
        "Submit an application for the matching applicant.",
        "Inspect the application status and compliance alerts."
      ],
      "expected_result": "The application status is set to BLOCKED, and the compliance team receives an alert for the match."
    },
    {
      "case_id": "TC04",
      "title": "Full-name-only match sends the application for analyst review",
      "covers": ["AC3"],
      "preconditions": [
        "The active sanctions list contains an entry matching the applicant's full name but not the applicant's date of birth."
      ],
      "steps": [
        "Submit an application for the applicant.",
        "Inspect the application status and review queue."
      ],
      "expected_result": "The application status is set to PENDING_REVIEW and is available for an analyst to decide."
    },
    {
      "case_id": "TC05",
      "title": "Application with no sanctions-list match passes screening",
      "covers": ["AC4"],
      "preconditions": [
        "The active sanctions list contains no match for the applicant."
      ],
      "steps": [
        "Submit an application for the applicant.",
        "Inspect the screening result and application progression."
      ],
      "expected_result": "Screening passes, and the application continues through the account-opening process."
    },
    {
      "case_id": "TC06",
      "title": "Blocked applicant sees the approved message without sanctions details",
      "covers": ["AC2", "AC5"],
      "preconditions": [
        "The active sanctions list contains an entry matching the applicant's full name and date of birth."
      ],
      "steps": [
        "Submit an application for the matching applicant.",
        "View the applicant-facing application outcome."
      ],
      "expected_result": "The application is BLOCKED, and the applicant is shown exactly: \"We cannot open an account at this time\". The message and applicant-facing outcome do not disclose or imply that the block was caused by a sanctions match."
    }
  ]
}

{
  "story_id": "K07",
  "test_cases": [
    {
      "case_id": "TC01",
      "title": "Open an EDD case for a qualifying first deposit",
      "covers": ["AC1", "AC3"],
      "preconditions": [
        "A customer account was opened 10 days ago.",
        "The account has not previously received a deposit."
      ],
      "steps": [
        "Make a first deposit of 10,000.01."
      ],
      "expected_result": "An EDD case is opened, and the customer is asked to provide a source-of-funds document within 14 days."
    },
    {
      "case_id": "TC02",
      "title": "Do not open an EDD case for a first deposit of exactly 10,000.00",
      "covers": ["AC2"],
      "preconditions": [
        "A customer account was opened 10 days ago.",
        "The account has not previously received a deposit."
      ],
      "steps": [
        "Make a first deposit of exactly 10,000.00."
      ],
      "expected_result": "No EDD case is opened."
    },
    {
      "case_id": "TC03",
      "title": "Open an EDD case for a qualifying first deposit on day 30",
      "covers": ["AC1"],
      "preconditions": [
        "A customer account was opened exactly 30 days ago.",
        "The account has not previously received a deposit."
      ],
      "steps": [
        "Make a first deposit of 10,000.01."
      ],
      "expected_result": "An EDD case is opened."
    },
    {
      "case_id": "TC04",
      "title": "Do not open an EDD case for a large first deposit after day 30",
      "covers": ["AC1"],
      "preconditions": [
        "A customer account was opened 31 days ago.",
        "The account has not previously received a deposit."
      ],
      "steps": [
        "Make a first deposit of 10,000.01."
      ],
      "expected_result": "No EDD case is opened."
    },
    {
      "case_id": "TC05",
      "title": "Keep the account unfrozen when the document is received within 14 days",
      "covers": ["AC3", "AC4"],
      "preconditions": [
        "An EDD case is open and the customer has been asked for a source-of-funds document.",
        "The account is not frozen."
      ],
      "steps": [
        "Submit the requested source-of-funds document within 14 days of the request.",
        "Check the account status."
      ],
      "expected_result": "The document is received within the required period, and the account does not change to FROZEN due to a missed document deadline."
    },
    {
      "case_id": "TC06",
      "title": "Freeze the account when the source-of-funds document is not received within 14 days",
      "covers": ["AC3", "AC4"],
      "preconditions": [
        "An EDD case is open and the customer has been asked for a source-of-funds document.",
        "The account is not frozen."
      ],
      "steps": [
        "Allow 14 days to pass without receiving the document.",
        "Check the account status."
      ],
      "expected_result": "The account status changes to FROZEN."
    },
    {
      "case_id": "TC07",
      "title": "Block withdrawals and transfers from a frozen account until the EDD case is closed",
      "covers": ["AC5"],
      "preconditions": [
        "The account is FROZEN because the source-of-funds document was not received within 14 days.",
        "The EDD case is still open."
      ],
      "steps": [
        "Attempt to make a withdrawal.",
        "Attempt to make a transfer.",
        "Have an analyst close the EDD case.",
        "Attempt a withdrawal and a transfer again."
      ],
      "expected_result": "The withdrawal and transfer are blocked while the account is frozen and the EDD case is open. After the analyst closes the EDD case, the account is no longer prevented from making withdrawals or transfers by this restriction."
    }
  ]
}

{
