      "case_id": "TC02",
      "title": "Calculate next review due date for MEDIUM-risk customer",
      "covers": ["AC1"],
      "preconditions": [
        "A customer has MEDIUM risk and a recorded last review date of 2025-03-10.",
        "The customer's local calendar has no non-business days affecting the calculated due date."
